package com.example.minicommerce.refund.infrastructure;import java.util.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import jakarta.persistence.LockModeType;public interface RefundRepository extends JpaRepository<RefundEntity,UUID>{Optional<RefundEntity>findByPaymentIdAndKey(UUID paymentId,String key);@Lock(LockModeType.PESSIMISTIC_WRITE)@Query("select r from RefundEntity r where r.id=:id")Optional<RefundEntity>findForUpdate(@Param("id")UUID id);}
